shellCommands.command:
mkdir -p .tmp-test && cat > .tmp-test/storage.test.ts <<'EOF'
import { describe, it, expect, beforeEach } from 'vitest';
import { readStoredTheme, writeStoredTheme, THEME_STORAGE_KEY } from '../src/themeStorage';
const mem = new Map<string,string>();
(globalThis as any).window = { localStorage: {
  getItem: (k: string) => mem.get(k) ?? null, setItem: (k: string, v: string) => void mem.set(k, v) } };
describe('themeStorage', () => {
  beforeEach(() => mem.clear());
  it('default', () => expect(readStoredTheme()).toBe('light'));
  it('roundtrip', () => { writeStoredTheme('dark'); expect(mem.get(THEME_STORAGE_KEY)).toBe('dark'); expect(readStoredTheme()).toBe('dark'); });
  it('garbage', () => { mem.set(THEME_STORAGE_KEY, 'neon'); expect(readStoredTheme()).toBe('light'); });
  it('throwing storage', () => {
    const w = (globalThis as any).window; const saved = w.localStorage;
    w.localStorage = { getItem() { throw new Error('denied'); }, setItem() { throw new Error('denied'); } };
    expect(readStoredTheme()).toBe('light'); expect(() => writeStoredTheme('dark')).not.toThrow();
    w.localStorage = saved;
  });
});
EOF
npx vitest run --root . .tmp-test 2>&1 | tail -8; rm -rf .tmp-test
